fn holds(&self, value: f64) -> bool {
    self.bounds.iter().all(|(key, bound)| match key.as_str() {
        "minimum" | "ge" => value >= *bound,
        "maximum" | "le" => value <= *bound,
        "exclusiveMinimum" | "gt" => value > *bound,
        "exclusiveMaximum" | "lt" => value < *bound,
        _ => true,
    })
}

